local GlassFritMaker = {}
local PRODUCTS = {
    iron_glass_frit = { name = "Železni frit za steklo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 170, prestige = 4, happiness = 2, description = "Železni frit za emajliranje stekla." },
    bronze_glass_frit = { name = "Bronast frit za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 415, prestige = 6, happiness = 3, description = "Bronast frit za fine emajle." },
    silver_glass_frit = { name = "Srebrni frit za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1000, prestige = 11, happiness = 4, description = "Srebrni frit za plemiške emajle." },
    gilded_glass_frit = { name = "Pozlačeni frit za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2150, prestige = 20, happiness = 5, description = "Pozlačeni frit za dvorne emajle." },
    jewel_set_glass_frit = { name = "Draguljasti frit za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4650, prestige = 36, happiness = 7, description = "Draguljasti frit za kraljevske emajle." },
    royal_sovereign_glass_frit = { name = "Kraljevski suvereni frit za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10000, prestige = 68, happiness = 13, description = "Suvereni frit z biseri za krono." },
}
local BUILDINGS = {
    glassfrit_workshop = { name = "Fritna delavnica", cost = { gold = 345, wood = 180, stone = 135, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    glassfrit_house = { name = "Fritna hiša", cost = { gold = 1225, wood = 365, stone = 275, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_glassfrit_atelier = { name = "Mojstrski fritni atelje", cost = { gold = 3060, wood = 420, stone = 525, silver = 36, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_glassfrit_palace = { name = "Suverena fritna palača", cost = { gold = 13100, wood = 650, stone = 835, gold = 84, jewel = 19 }, upkeep = 257, qualityBonus = 55, prestigeBonus = 50 },
}
GlassFritMaker.ironStock = 14; GlassFritMaker.bronzeStock = 12; GlassFritMaker.woodStock = 12; GlassFritMaker.leatherStock = 10; GlassFritMaker.silverStock = 8; GlassFritMaker.goldStock = 6; GlassFritMaker.jewelStock = 4; GlassFritMaker.pearlStock = 4
GlassFritMaker.productStock = {}; GlassFritMaker.buildings = {}; GlassFritMaker.maker = nil; GlassFritMaker.activeMaking = {}; GlassFritMaker.totalProducts = 0; GlassFritMaker.dayTimer = 0
function GlassFritMaker.init() GlassFritMaker.ironStock=14; GlassFritMaker.bronzeStock=12; GlassFritMaker.woodStock=12; GlassFritMaker.leatherStock=10; GlassFritMaker.silverStock=8; GlassFritMaker.goldStock=6; GlassFritMaker.jewelStock=4; GlassFritMaker.pearlStock=4; GlassFritMaker.productStock={}; GlassFritMaker.buildings={}; GlassFritMaker.maker=nil; GlassFritMaker.activeMaking={}; GlassFritMaker.totalProducts=0; GlassFritMaker.dayTimer=0; print("[GlassFritMaker] Royal Glass Frit Maker System initialized (6 products, 4 buildings)") end
function GlassFritMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassFritMaker.maker={name=n or ("Fritar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Fritar najet: %s (spretnost: %d)",GlassFritMaker.maker.name,s),"success") end; return true end
function GlassFritMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassFritMaker.build(id) local ok,e=GlassFritMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassFritMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassFritMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassFritMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassFritMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassFritMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassFritMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassFritMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassFritMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassFritMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassFritMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassFritMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassFritMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassFritMaker.buildings==0 then return false,"Potrebna fritna delavnica" end; if not GlassFritMaker.maker then return false,"Potreben fritar" end; return true end
function GlassFritMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassFritMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassFritMaker.ironStock=GlassFritMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassFritMaker.bronzeStock=GlassFritMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassFritMaker.woodStock=GlassFritMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassFritMaker.leatherStock=GlassFritMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassFritMaker.silverStock=GlassFritMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassFritMaker.goldStock=GlassFritMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassFritMaker.jewelStock=GlassFritMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassFritMaker.pearlStock=GlassFritMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassFritMaker.maker then t=math.max(1,t-math.floor(GlassFritMaker.maker.skill/13)) end; table.insert(GlassFritMaker.activeMaking,{id="glassfrit_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassFritMaker.completeMaking(m) local q=1.0+(GlassFritMaker.getQualityBonus()/100); if GlassFritMaker.maker then q=q+(GlassFritMaker.maker.skill/140) end; q=math.min(2.5,q); GlassFritMaker.productStock[m.productType]=(GlassFritMaker.productStock[m.productType] or 0)+m.quantity; GlassFritMaker.totalProducts=GlassFritMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassFritMaker.maker then GlassFritMaker.maker.itemsMade=GlassFritMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassFritMaker.maker.skill=math.min(100,GlassFritMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Frit izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassfrit.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassFritMaker.update(dt) if not _G.state then return end; GlassFritMaker.dayTimer=GlassFritMaker.dayTimer+dt; if GlassFritMaker.dayTimer>=30 then GlassFritMaker.dayTimer=0; for i=#GlassFritMaker.activeMaking,1,-1 do local m=GlassFritMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassFritMaker.completeMaking(m); table.remove(GlassFritMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassFritMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassFritMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassFritMaker.getStats() return {ironStock=GlassFritMaker.ironStock,bronzeStock=GlassFritMaker.bronzeStock,woodStock=GlassFritMaker.woodStock,leatherStock=GlassFritMaker.leatherStock,silverStock=GlassFritMaker.silverStock,goldStock=GlassFritMaker.goldStock,jewelStock=GlassFritMaker.jewelStock,pearlStock=GlassFritMaker.pearlStock,productStock=GlassFritMaker.productStock,numBuildings=#GlassFritMaker.buildings,hasMaker=GlassFritMaker.maker~=nil,makerName=GlassFritMaker.maker and GlassFritMaker.maker.name or "—",makerSkill=GlassFritMaker.maker and GlassFritMaker.maker.skill or 0,activeMaking=#GlassFritMaker.activeMaking,totalProducts=GlassFritMaker.totalProducts} end
return GlassFritMaker
